lessons.example:
SELECT first_name, last_name, salary
FROM employees
WHERE salary > (
  SELECT AVG(salary)
  FROM employees
);

SELECT first_name, last_name, salary,
  RANK() OVER (ORDER BY salary DESC) AS salary_rank
FROM employees;

SELECT id, order_date,
  LAG(order_date) OVER (ORDER BY order_date) AS previous_order_date
FROM orders;
